1: @model StudentEditPageModel
2: @{var canEdit=Model.CanEdit;var codes=Model.Lookups.Codes;var today=WebPresentation.BusinessDate;var input=Model.Input;var cls=Model.Lookups.Classes.FirstOrDefault(c=>c.ClassId.ToString()==input.ClassId);}
3: <h1>学生登録 @(Model.StudentId is null?"／新規":canEdit?"／編集":"／参照")</h1><partial name="_MessagePanel" model="Model.Message" />
4: <p>学生管理番号 @(Model.StudentId?.ToString()??"新規")　更新日時 @(Model.Detail is null?"－":WebPresentation.Time(Model.Detail.UpdatedAt))　更新者 @(Model.Detail?.UpdatedBy??"－")</p>
5: <form method="post" action="@(Model.StudentId is null?"/students/create":$"/students/{Model.StudentId}/update")" data-editor-form>@Html.AntiForgeryToken()<input type="hidden" name="SnapshotId" value="@Model.SnapshotId"><input asp-for="Input.ExpectedVersion" type="hidden"><input asp-for="Input.ReturnContextId" type="hidden"><input asp-for="Input.DuplicateToken" type="hidden"><fieldset disabled="@(!canEdit)"><legend>学生基本情報</legend><div class="fields">
6: <label>学籍番号 ※必須<input asp-for="Input.StudentNo" id="REG-002" maxlength="30" readonly="@(Model.StudentId is not null)" required></label><label>氏名 ※必須<input asp-for="Input.StudentName" id="REG-003" maxlength="16" required><small>8文字以内</small></label><label>氏名カナ ※必須<input asp-for="Input.StudentNameKana" id="REG-004" maxlength="72" required><small>原入力36、正規化後18文字</small></label>
7: <fieldset class="wareki" id="REG-005"><legend>生年月日 ※必須</legend><select asp-for="Input.BirthDateInput.Era" aria-label="元号" required><option value="">元号</option><option value="REIWA">令和</option><option value="HEISEI">平成</option><option value="SHOWA">昭和</option><option value="TAISHO">大正</option><option value="MEIJI">明治</option></select><input asp-for="Input.BirthDateInput.Year" aria-label="元号年" maxlength="4" required><span>年</span><input asp-for="Input.BirthDateInput.Month" aria-label="月" maxlength="2" required><span>月</span><input asp-for="Input.BirthDateInput.Day" aria-label="日" maxlength="2" required><span>日</span></fieldset>
8: <label>性別 ※必須<select asp-for="Input.GenderCode" id="REG-006" required>@foreach(var c in codes.Where(c=>c.CategoryId=="GENDER")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.GenderCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName @(!selectable?"（停止・期間外）":"")</option>}</select></label>
9: <label>郵便番号 ※必須<input asp-for="Input.PostalCode" id="REG-007" maxlength="20" required></label><label>都道府県 ※必須<select asp-for="Input.PrefectureCode" id="REG-008" required><option value="">未選択</option>@foreach(var c in codes.Where(c=>c.CategoryId=="PREFECTURE")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.PrefectureCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName @(!selectable?"（停止・期間外）":"")</option>}</select></label>
10: <label>住所1 ※必須<input asp-for="Input.AddressLine1" id="REG-009" maxlength="90" required><small>45文字以内</small></label><label>住所2<input asp-for="Input.AddressLine2" id="REG-010" maxlength="90"></label><label>本人電話<input asp-for="Input.PhoneNumber" id="REG-011" maxlength="40"><small>原入力20、正規化後16文字</small></label><label>本人メール<input asp-for="Input.EmailAddress" id="REG-012" maxlength="120"></label>
11: <label>入学日 ※必須<input asp-for="Input.AdmissionDate" id="REG-013" type="date" required></label><label>在籍区分 ※必須<select asp-for="Input.EnrollmentStatusCode" id="REG-014" required>@foreach(var c in codes.Where(c=>c.CategoryId=="ENROLLMENT_STATUS")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.EnrollmentStatusCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName</option>}</select></label><label>卒業・退学日<input asp-for="Input.EnrollmentEndDate" id="REG-015" type="date"></label>
12: <label>年度<select asp-for="Input.SchoolYear" id="REG-016"><option value="">未指定</option>@foreach(var y in Model.Lookups.Classes.Select(c=>c.SchoolYear).Concat(input.SchoolYear.HasValue?[input.SchoolYear.Value]:[]).Distinct().OrderDescending()){<option value="@y">@y</option>}</select></label><label>学年<select asp-for="Input.GradeCode" id="REG-017"><option value="">すべて</option>@foreach(var c in codes.Where(c=>c.CategoryId=="GRADE")){<option value="@c.CodeValue">@c.CodeName</option>}</select></label><label>クラス<select asp-for="Input.ClassId" id="REG-018"><option value="">未所属</option>@foreach(var c in Model.Lookups.Classes){bool active=c.IsActive&&c.ValidFrom<=today&&today<=c.ValidTo;bool terminal=input.EnrollmentStatusCode is "03" or "04";bool overlap=DateOnly.TryParse(input.AdmissionDate,out var a)&&DateOnly.TryParse(input.EnrollmentEndDate,out var e)&&c.ValidFrom<=e&&a<=c.ValidTo;bool keep=Model.Detail?.Draft.ClassId==c.ClassId;bool selectable=keep||(terminal?overlap:active);<option value="@c.ClassId" data-year="@c.SchoolYear" data-grade="@c.GradeCode" disabled="@(!selectable)">@c.SchoolYear @c.GradeCode @c.ClassCode @c.ClassName @(!c.IsActive?"（停止）":!active?"（期間外）":"")</option>}</select><small>人数 @(cls?.Occupied.ToString()??"－")／定員 @(cls?.Capacity.ToString()??"制限なし")（参考）</small></label>
13: <label>緊急連絡先氏名<input asp-for="Input.EmergencyContactName" id="REG-020" maxlength="16"></label><label>緊急連絡先続柄<select asp-for="Input.RelationshipCode" id="REG-021"><option value="">未選択</option>@foreach(var c in codes.Where(c=>c.CategoryId=="RELATIONSHIP")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.RelationshipCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName</option>}</select></label><label>緊急連絡先電話<input asp-for="Input.EmergencyPhoneNumber" id="REG-022" maxlength="40"></label><label class="full">備考<textarea asp-for="Input.Remarks" id="REG-023" maxlength="240"></textarea></label><label class="full">確認・変更理由<textarea asp-for="Input.OperationReason" id="REG-024" maxlength="120"></textarea></label></div><p>本人電話・メール・緊急電話のいずれか1つ以上。緊急連絡先は3項目すべて入力してください。</p>
14: @if(Model.Result?.Outcome==Outcome.ConfirmationRequired){<section role="dialog" aria-labelledby="duplicate-title" class="warning"><h2 id="duplicate-title">同一人物候補の確認</h2><p>全 @Model.Result.CandidateCount 件、最大20件表示</p><table><thead><tr><th>学籍番号</th><th>氏名</th><th>和暦生年月日</th><th>クラス</th></tr></thead><tbody>@foreach(var c in (Model.Result.Candidates??[]).Take(20)){<tr><td>@c.StudentNo</td><td>@c.StudentName</td><td>@c.BirthDateWareki</td><td>@c.ClassName</td></tr>}</tbody></table><p>別人と確認した場合は、確認理由を入力して続行してください。</p><button type="button" data-cancel-duplicate autofocus>確認取消</button><button type="submit" data-confirm="別人として保存しますか。">別人と確認して続行</button></section>}
15: <div class="actions"><button type="submit" class="primary">@(Model.StudentId is null?"登録":"更新")</button></div></fieldset></form>
16: <div class="actions"><form method="post" action="/students/reset" data-confirm="編集内容を読込時の値へ戻しますか。">@Html.AntiForgeryToken()<input type="hidden" name="SnapshotId" value="@Model.SnapshotId"><input type="hidden" name="StudentId" value="@Model.StudentId"><button>@(Model.StudentId is null?"入力クリア":"編集取消")</button></form>@if(Model.StudentId is not null){<a data-dirty-link data-confirm="編集内容を破棄して最新情報を読み込みますか。" href="/students/@Model.StudentId?returnContextId=@input.ReturnContextId">最新情報を再読込</a>}<a data-dirty-link href="/students?contextId=@input.ReturnContextId&amp;contextRevision=@Model.ReturnRevision">検索へ戻る</a></div>
17: @if(Model.StudentId is not null&&Model.User.Role==Role.Administrator){<form method="post" action="/students/@Model.StudentId/delete" data-confirm="対象と理由を確認して論理削除しますか。">@Html.AntiForgeryToken()<input type="hidden" name="SnapshotId" value="@Model.SnapshotId"><input type="hidden" name="ExpectedVersion" value="@input.ExpectedVersion"><input type="hidden" name="ReturnContextId" value="@input.ReturnContextId"><input type="hidden" name="Confirmed" value="true"><label>削除理由 ※必須<textarea name="Reason" id="REG-026" maxlength="120" required></textarea></label><button class="danger">対象を確認して論理削除</button><p>編集中の業務値は保存されません。</p></form>}

